"use client";
import Link from "next/link";
import { useMemo, useState } from "react";
import { Icon, NetworkMark } from "@/components/UI";
import styles from "./Portal.module.css";

const PARTNER_TERMS_VERSION = "rede-conecta-non-circumvention-2026-07-27";
const connectionStatus = {
  new: "Novo", assigned: "Distribuído", accepted: "Aceito", contacted: "Contatado", qualified: "Qualificado",
  visit_scheduled: "Visita", proposal: "Proposta", won: "Ganho", lost: "Perdido", cancelled: "Cancelado"
};
const dealStatus = { draft: "Rascunho", reservation: "Reserva", contract_pending: "Contrato pendente", contracted: "Contratado", validated: "Validado", cancelled: "Cancelado", lost: "Perdido" };

function money(cents) { return new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(Number(cents || 0) / 100); }
function when(value) { if (!value) return "—"; return new Intl.DateTimeFormat("pt-BR", { dateStyle: "short", timeStyle: "short" }).format(new Date(value)); }
function dateOnly(value) { if (!value) return "—"; return new Intl.DateTimeFormat("pt-BR", { dateStyle: "short" }).format(new Date(value)); }
function slugify(value) { return String(value || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""); }

async function request(operation, params = {}) {
  const response = await fetch("/api/app/rpc", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ operation, params }) });
  const payload = await response.json();
  if (response.status === 401) { location.href = "/entrar?expirado=1"; throw new Error("Sessão expirada."); }
  if (!response.ok) throw new Error(payload.error || "Não foi possível concluir a operação.");
  return payload.data;
}

function Toast({ toast, onClose }) {
  if (!toast) return null;
  return <div className={`${styles.toast} ${toast.type === "error" ? styles.toastError : ""}`}><Icon name={toast.type === "error" ? "shield" : "check"} size={18}/><span>{toast.message}</span><button onClick={onClose}>×</button></div>;
}

function Modal({ title, children, onClose, wide = false }) {
  return <div className={styles.modalBackdrop} onMouseDown={event => event.target === event.currentTarget && onClose()}><div className={`${styles.modal} ${wide ? styles.modalWide : ""}`}><header><h2>{title}</h2><button onClick={onClose} aria-label="Fechar">×</button></header><div className={styles.modalBody}>{children}</div></div></div>;
}

function Metric({ label, value, note, icon = "chart" }) {
  return <article className={styles.metric}><div className={styles.metricIcon}><Icon name={icon}/></div><span>{label}<b>{value}</b>{note && <small>{note}</small>}</span></article>;
}

function Empty({ children = "Nenhum registro encontrado." }) { return <div className={styles.empty}><Icon name="check"/><p>{children}</p></div>; }
function Status({ value }) { return <span className={`${styles.status} ${["active","approved","paid","validated","won","sent","completed","resolved"].includes(value) ? styles.statusGood : ["rejected","failed","cancelled","lost","suspended","critical"].includes(value) ? styles.statusBad : ""}`}>{connectionStatus[value] || dealStatus[value] || String(value || "—").replaceAll("_", " ")}</span>; }

function Field({ label, children }) { return <label className={styles.field}><span>{label}</span>{children}</label>; }

function PendingPortal({ context }) {
  return <div className={styles.pending}><NetworkMark/><div className={styles.pendingIcon}><Icon name="clock" size={36}/></div><span className="eyebrow">Cadastro em validação</span><h1>Olá, {context.display_name}.</h1><p>Sua conta foi criada e o cadastro está aguardando análise da equipe da Rede Conecta. Após a aprovação, você receberá uma confirmação por e-mail e WhatsApp e terá acesso aos produtos, links e acompanhamento.</p><div className={styles.securityCard}><Icon name="shield"/><span><b>Nenhuma indicação deve ser feita antes da liberação.</b> Isso preserva as regras da campanha, a atribuição e a segurança dos envolvidos.</span></div><button className="button button--light" onClick={() => fetch("/api/auth/logout", { method: "POST" }).then(() => location.href = "/")}>Sair</button></div>;
}

function StaffDashboard({ data }) {
  const d = data || {};
  return <><div className={styles.metrics}>
    <Metric icon="user" label="Cadastros para análise" value={d.pending_connectors || 0} note="Conectores pendentes"/>
    <Metric icon="link" label="Conectores ativos" value={d.active_connectors || 0} note="Aptos a compartilhar"/>
    <Metric icon="target" label="Leads em andamento" value={d.open_connections || 0} note={`${d.overdue_tasks || 0} tarefas vencidas`}/>
    <Metric icon="money" label="VGV validado" value={money(d.validated_vgv_cents)} note={`${d.open_deals || 0} negócios abertos`}/>
  </div><div className={styles.dashboardGrid}>
    <section className={styles.card}><div className={styles.cardHead}><h2>Controle operacional</h2><Status value={d.open_circumvention_alerts ? "critical" : "active"}/></div><div className={styles.controlList}>
      <span><b>{d.active_partners || 0}</b> parceiros ativos</span><span><b>{d.active_brokers || 0}</b> corretores cadastrados</span><span><b>{money(d.pending_rewards_cents)}</b> em recompensas pendentes</span><span><b>{d.notification_backlog || 0}</b> comunicações na fila</span>
    </div></section>
    <section className={`${styles.card} ${styles.cardDark}`}><span className="eyebrow">Proteção da origem</span><h2>Parceiros não recebem dados pessoais nem operam leads.</h2><p>Relacionamento, produto de origem, janela de proteção, atividade, negócio, recompensa e conciliação permanecem registrados pela Rede Conecta.</p><div className={styles.darkStats}><span><b>{d.open_circumvention_alerts || 0}</b>alertas de conciliação</span><span><b>{d.overdue_tasks || 0}</b>tarefas vencidas</span></div></section>
  </div></>;
}

function ConnectorsSection({ data, onAction, processing }) {
  const [filter, setFilter] = useState("all");
  const list = (data || []).filter(item => filter === "all" || item.status === filter);
  async function review(item, decision) {
    const reason = decision === "reject" ? prompt("Informe o motivo objetivo da rejeição:", "Cadastro não atende aos critérios atuais da Rede Conecta.") : "";
    if (decision === "reject" && reason === null) return;
    await onAction("review_connector", { p_application_id: item.id, p_decision: decision, p_notes: "", p_reason: reason || "" }, true);
    if (decision === "approve" || decision === "reject") await processing();
  }
  return <section className={styles.card}><div className={styles.sectionHead}><div><span className="eyebrow">Gestão de conectores</span><h2>Cadastros, validação e liberação</h2></div><div className={styles.filters}>{["all","pending","under_review","approved","rejected"].map(status => <button className={filter === status ? styles.activeFilter : ""} key={status} onClick={() => setFilter(status)}>{status === "all" ? "Todos" : status.replaceAll("_", " ")}</button>)}</div></div>
    <div className={styles.tableWrap}><table><thead><tr><th>Conector</th><th>Contato</th><th>Rede</th><th>Status</th><th>Data</th><th>Ações</th></tr></thead><tbody>{list.map(item => <tr key={item.id}><td><b>{item.full_name}</b><small>{item.city}{item.state ? ` · ${item.state}` : ""}</small></td><td><span>{item.email}</span><small>{item.phone}</small></td><td><span>{item.occupation || "—"}</span><small title={item.network_profile}>{item.network_profile?.slice(0, 70) || "Não informado"}</small></td><td><Status value={item.status}/></td><td>{dateOnly(item.created_at)}</td><td><div className={styles.rowActions}>{!['approved','rejected'].includes(item.status) && <><button onClick={() => review(item, "under_review")}>Analisar</button><button className={styles.goodButton} onClick={() => review(item, "approve")}>Aprovar</button><button className={styles.dangerButton} onClick={() => review(item, "reject")}>Rejeitar</button></>}</div></td></tr>)}</tbody></table></div>{!list.length && <Empty/>}
  </section>;
}

function StaffSection({ data, onAction }) {
  const [result, setResult] = useState(null);
  const staff = data?.staff || [];
  const roles = data?.roles || [];
  async function invite(event) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const created = await onAction("create_account_invite", {
      p_target_kind: "staff", p_email: form.get("email"), p_phone: form.get("phone"), p_display_name: form.get("displayName"),
      p_partner_id: null, p_access_role_code: form.get("accessRole"), p_membership_role: form.get("membershipRole"), p_metadata: {}, p_expires_in_days: 7
    }, false);
    setResult(created); event.currentTarget.reset();
  }
  return <div className={styles.twoColumn}><section className={styles.card}><div className={styles.cardHead}><div><span className="eyebrow">Equipe interna</span><h2>Usuários e papéis</h2></div></div>{staff.map(member => <div className={styles.personRow} key={member.profile_id}><span className={styles.avatar}>{member.display_name?.split(" ").map(v => v[0]).slice(0,2).join("")}</span><span><b>{member.display_name}</b><small>{member.email}</small></span><div className={styles.roleTags}>{(member.access_roles || []).map(role => <i key={role}>{role.replaceAll("_", " ")}</i>)}</div><Status value={member.status}/></div>)}{!staff.length && <Empty/>}</section>
    <section className={styles.card}><span className="eyebrow">Novo acesso</span><h2>Convidar integrante</h2><form className={styles.form} onSubmit={invite}><Field label="Nome"><input name="displayName" required/></Field><Field label="E-mail"><input name="email" type="email" required/></Field><Field label="WhatsApp"><input name="phone" inputMode="tel"/></Field><Field label="Papel interno"><select name="accessRole" required>{roles.map(role => <option key={role.code} value={role.code}>{role.name}</option>)}</select></Field><Field label="Papel organizacional"><select name="membershipRole"><option value="manager">Gestor</option><option value="finance">Financeiro</option><option value="training">Treinamento</option><option value="read_only">Leitura</option><option value="owner">Proprietário</option></select></Field><button className="button button--orange">Criar convite seguro</button></form>{result && <div className={styles.resultBox}><b>Convite criado</b><code>{result.activation_url}</code><button onClick={() => navigator.clipboard.writeText(result.activation_url)}>Copiar link</button></div>}</section>
  </div>;
}

function PartnersSection({ data, onAction }) {
  const [editing, setEditing] = useState(null);
  const [inviteResult, setInviteResult] = useState(null);
  const partners = data || [];
  async function save(event) {
    event.preventDefault(); const form = new FormData(event.currentTarget);
    const payload = Object.fromEntries(form.entries());
    payload.reconciliation_required = form.get("reconciliation_required") === "on";
    const saved = await onAction("upsert_partner", { p_partner_id: editing?.id || null, p_payload: payload }, true);
    setEditing(null); return saved;
  }
  async function invitePartnerUser(event) {
    event.preventDefault(); const form = new FormData(event.currentTarget);
    const created = await onAction("create_account_invite", { p_target_kind: "partner_user", p_email: form.get("email"), p_phone: form.get("phone"), p_display_name: form.get("displayName"), p_partner_id: form.get("partnerId"), p_access_role_code: null, p_membership_role: "read_only", p_metadata: { access_scope: form.get("accessScope") }, p_expires_in_days: 7 }, false);
    setInviteResult(created); event.currentTarget.reset();
  }
  return <><div className={styles.sectionHead}><div><span className="eyebrow">Loteadoras e incorporadoras</span><h2>Parceiros sob operação centralizada</h2></div><button className="button button--orange" onClick={() => setEditing({})}>Cadastrar parceiro</button></div><div className={styles.gridCards}>{partners.map(partner => <article className={styles.card} key={partner.id}><div className={styles.cardHead}><div><h3>{partner.name}</h3><small>{partner.legal_name || partner.partner_type}</small></div><Status value={partner.status}/></div><dl className={styles.definition}><dt>Contrato</dt><dd><Status value={partner.contract_status}/></dd><dt>Proteção</dt><dd>{partner.attribution_window_days} dias</dd><dt>Empreendimentos</dt><dd>{partner.development_count}</dd><dt>Conexões protegidas</dt><dd>{partner.protected_connection_count}</dd><dt>Reconciliação</dt><dd>{partner.reconciliation_required ? "Obrigatória" : "Não exigida"}</dd></dl><div className={styles.securityCard}><Icon name="shield"/><span><b>Não circunvenção</b>{partner.terms_accepted_at ? `Aceita em ${dateOnly(partner.terms_accepted_at)}` : "Aceite ainda pendente"}</span></div><button className="button button--light" onClick={() => setEditing(partner)}>Editar cadastro</button></article>)}</div>{!partners.length && <Empty/>}
    <section className={styles.card} style={{ marginTop: 18 }}><span className="eyebrow">Painel de leitura do parceiro</span><h2>Convidar usuário do empreendedor</h2><form className={styles.inlineForm} onSubmit={invitePartnerUser}><input name="displayName" required placeholder="Nome"/><input name="email" type="email" required placeholder="E-mail"/><input name="phone" placeholder="WhatsApp"/><select name="partnerId" required><option value="">Parceiro</option>{partners.map(p => <option value={p.id} key={p.id}>{p.name}</option>)}</select><select name="accessScope"><option value="executive">Executivo</option><option value="commercial">Comercial</option><option value="finance">Financeiro</option><option value="legal">Jurídico</option><option value="read_only">Leitura geral</option></select><button className="button button--navy">Criar convite</button></form>{inviteResult && <div className={styles.resultBox}><b>Link de ativação</b><code>{inviteResult.activation_url}</code><button onClick={() => navigator.clipboard.writeText(inviteResult.activation_url)}>Copiar</button></div>}</section>
    {editing && <Modal title={editing.id ? "Editar parceiro" : "Cadastrar parceiro"} onClose={() => setEditing(null)}><form className={styles.form} onSubmit={save}><div className={styles.formGrid}><Field label="Nome da marca"><input name="name" defaultValue={editing.name} required/></Field><Field label="Razão social"><input name="legal_name" defaultValue={editing.legal_name}/></Field><Field label="CNPJ"><input name="tax_id" defaultValue={editing.tax_id}/></Field><Field label="Tipo"><select name="partner_type" defaultValue={editing.partner_type || "developer"}><option value="developer">Loteadora</option><option value="incorporator">Incorporadora</option><option value="real_estate">Imobiliária</option><option value="landowner">Terrenista</option><option value="builder">Construtora</option><option value="other">Outro</option></select></Field><Field label="Status"><select name="status" defaultValue={editing.status || "pending"}><option value="pending">Pendente</option><option value="active">Ativo</option><option value="paused">Pausado</option><option value="terminated">Encerrado</option></select></Field><Field label="Contrato"><select name="contract_status" defaultValue={editing.contract_status || "pending"}><option value="pending">Pendente</option><option value="active">Ativo</option><option value="expired">Expirado</option><option value="terminated">Encerrado</option></select></Field><Field label="Janela de proteção (dias)"><input name="attribution_window_days" type="number" min="1" max="730" defaultValue={editing.attribution_window_days || 180}/></Field><Field label="Versão do termo"><input name="terms_version" defaultValue={editing.non_circumvention_terms_version}/></Field><Field label="Responsável"><input name="contact_name" defaultValue={editing.contact_name}/></Field><Field label="E-mail"><input name="email" type="email" defaultValue={editing.email}/></Field><Field label="WhatsApp"><input name="phone" defaultValue={editing.phone}/></Field><Field label="E-mail jurídico"><input name="legal_email" type="email" defaultValue={editing.legal_email}/></Field></div><label className={styles.check}><input name="reconciliation_required" type="checkbox" defaultChecked={editing.reconciliation_required ?? true}/>Reconciliação periódica de vendas obrigatória</label><button className="button button--orange">Salvar parceiro</button></form></Modal>}
  </>;
}

function UploadButton({ bucket, folder, onUploaded }) {
  const [busy, setBusy] = useState(false);
  async function upload(event) {
    const file = event.target.files?.[0]; if (!file) return; setBusy(true);
    const form = new FormData(); form.append("file", file); form.append("bucket", bucket); form.append("folder", folder);
    const response = await fetch("/api/storage/upload", { method: "POST", body: form }); const data = await response.json(); setBusy(false);
    if (!response.ok) return alert(data.error || "Falha no envio."); onUploaded(data);
  }
  return <label className={styles.upload}>{busy ? "Enviando…" : "Enviar arquivo"}<input type="file" onChange={upload} disabled={busy}/></label>;
}

function CatalogSection({ data, onAction }) {
  const catalog = data?.catalog || { developments: [], products: [], campaigns: [] };
  const partners = data?.partners || [];
  const [development, setDevelopment] = useState(null);
  const [product, setProduct] = useState(null);
  async function saveDevelopment(event) {
    event.preventDefault(); const form = new FormData(event.currentTarget); const payload = Object.fromEntries(form.entries()); payload.public_visibility = form.get("public_visibility") === "on";
    await onAction("upsert_development", { p_development_id: development?.id || null, p_payload: payload }, true); setDevelopment(null);
  }
  async function saveProduct(event) {
    event.preventDefault(); const form = new FormData(event.currentTarget); const values = Object.fromEntries(form.entries());
    values.public_visibility = form.get("public_visibility") === "on"; values.training_required = form.get("training_required") === "on"; values.alternative_discovery_enabled = form.get("alternative_discovery_enabled") === "on";
    values.interest_options = String(values.interest_options || "").split("\n").map(v => v.trim()).filter(Boolean); values.metadata = { image: values.image || undefined, features: String(values.features || "").split("\n").map(v => v.trim()).filter(Boolean), area_from: values.area_from, payment: values.payment, location: values.location };
    await onAction("upsert_product_campaign", { p_product_id: product?.id || null, p_campaign_id: product?.campaign_id || null, p_payload: values }, true); setProduct(null);
  }
  const campaignByProduct = Object.fromEntries((catalog.campaigns || []).map(c => [c.product_id, c]));
  return <><div className={styles.sectionHead}><div><span className="eyebrow">Portfólio oficial</span><h2>Empreendimentos, produtos e campanhas</h2></div><div className="button-row"><button className="button button--light" onClick={() => setDevelopment({})}>Novo empreendimento</button><button className="button button--orange" onClick={() => setProduct({})}>Novo produto e campanha</button></div></div>
    <section className={styles.card}><h3>Empreendimentos</h3><div className={styles.tableWrap}><table><thead><tr><th>Nome</th><th>Parceiro</th><th>Localização</th><th>Status</th><th>Produtos</th><th></th></tr></thead><tbody>{catalog.developments.map(item => <tr key={item.id}><td><b>{item.name}</b><small>{item.category}</small></td><td>{item.partner_name || "—"}</td><td>{item.city} · {item.state}</td><td><Status value={item.status}/></td><td>{item.product_count}</td><td><button onClick={() => setDevelopment(item)}>Editar</button></td></tr>)}</tbody></table></div></section>
    <section className={styles.card} style={{ marginTop: 18 }}><h3>Produtos e campanhas</h3><div className={styles.gridCards}>{catalog.products.map(item => { const campaign = campaignByProduct[item.id]; return <article className={styles.productAdmin} key={item.id}><div><Status value={item.status}/><small>{item.category}</small></div><h3>{item.name}</h3><p>{item.description}</p><dl className={styles.definition}><dt>Campanha</dt><dd>{campaign?.title || "Sem campanha"}</dd><dt>Recompensa</dt><dd>{money(campaign?.reward_amount_cents || item.referral_bonus_cents)}</dd><dt>Publicação</dt><dd>{item.public_visibility ? "Público" : "Restrito"}</dd></dl><button className="button button--light" onClick={() => setProduct({ ...item, ...campaign, campaign_id: campaign?.id, product_name: item.name, product_slug: item.slug, product_status: item.status, campaign_status: campaign?.status, interest_options: campaign?.interest_options })}>Editar</button></article>; })}</div></section>
    {development && <Modal title={development.id ? "Editar empreendimento" : "Novo empreendimento"} onClose={() => setDevelopment(null)} wide><form className={styles.form} onSubmit={saveDevelopment}><div className={styles.formGrid}><Field label="Nome"><input name="name" required defaultValue={development.name} onBlur={e => { const slug = e.currentTarget.form.elements.slug; if (!slug.value) slug.value = `${slugify(e.target.value)}-empreendimento`; }}/></Field><Field label="Slug"><input name="slug" required defaultValue={development.slug}/></Field><Field label="Parceiro"><select name="partner_id" defaultValue={development.partner_id || ""}><option value="">Selecione</option>{partners.map(p => <option value={p.id} key={p.id}>{p.name}</option>)}</select></Field><Field label="Categoria"><input name="category" defaultValue={development.category}/></Field><Field label="Cidade"><input name="city" defaultValue={development.city}/></Field><Field label="Estado"><input name="state" maxLength="2" defaultValue={development.state}/></Field><Field label="Região de atendimento"><input name="service_region" defaultValue={development.service_region}/></Field><Field label="SLA de lead (minutos)"><input name="lead_sla_minutes" type="number" defaultValue={development.lead_sla_minutes || 30}/></Field><Field label="Unidades"><input name="unit_count" type="number" defaultValue={development.unit_count}/></Field><Field label="Status"><select name="status" defaultValue={development.status || "draft"}><option value="draft">Rascunho</option><option value="active">Ativo</option><option value="paused">Pausado</option><option value="sold_out">Esgotado</option><option value="archived">Arquivado</option></select></Field><Field label="Endereço"><input name="address" defaultValue={development.address}/></Field><Field label="Site"><input name="website_url" type="url" defaultValue={development.website_url}/></Field></div><Field label="Descrição"><textarea name="description" rows="4" defaultValue={development.description}/></Field><label className={styles.check}><input name="public_visibility" type="checkbox" defaultChecked={development.public_visibility}/>Visível no catálogo</label><button className="button button--orange">Salvar empreendimento</button></form></Modal>}
    {product && <Modal title={product.id ? "Editar produto e campanha" : "Novo produto e campanha"} onClose={() => setProduct(null)} wide><form className={styles.form} onSubmit={saveProduct}><div className={styles.formGrid}><Field label="Nome do produto"><input name="product_name" required defaultValue={product.product_name || product.name} onBlur={e => { const slug = e.currentTarget.form.elements.product_slug; if (!slug.value) slug.value = slugify(e.target.value); }}/></Field><Field label="Slug do produto"><input name="product_slug" required defaultValue={product.product_slug || product.slug}/></Field><Field label="Empreendimento"><select name="development_id" defaultValue={product.development_id || product.development_ids?.[0] || ""}><option value="">Selecione</option>{catalog.developments.map(d => <option value={d.id} key={d.id}>{d.name}</option>)}</select></Field><Field label="Parceiro"><select name="partner_id" defaultValue={product.partner_id || ""}><option value="">Selecione</option>{partners.map(p => <option value={p.id} key={p.id}>{p.name}</option>)}</select></Field><Field label="Categoria"><input name="category" defaultValue={product.category}/></Field><Field label="Região"><input name="service_region" defaultValue={product.service_region}/></Field><Field label="Status do produto"><select name="product_status" defaultValue={product.product_status || "draft"}><option value="draft">Rascunho</option><option value="active">Ativo</option><option value="paused">Pausado</option><option value="discontinued">Descontinuado</option><option value="archived">Arquivado</option></select></Field><Field label="Status comercial"><select name="commercial_status" defaultValue={product.commercial_status || "planning"}><option value="planning">Planejamento</option><option value="active">Ativo</option><option value="paused">Pausado</option></select></Field><Field label="Título da campanha"><input name="campaign_title" defaultValue={product.campaign_title || product.title || product.product_name || product.name}/></Field><Field label="Slug da campanha"><input name="campaign_slug" required defaultValue={product.campaign_slug || product.slug}/></Field><Field label="Localização"><input name="location" defaultValue={product.location}/></Field><Field label="Status da campanha"><select name="campaign_status" defaultValue={product.campaign_status || "draft"}><option value="draft">Rascunho</option><option value="active">Ativa</option><option value="paused">Pausada</option><option value="closed">Encerrada</option></select></Field><Field label="Recompensa em centavos"><input name="reward_amount_cents" type="number" defaultValue={product.reward_amount_cents || product.referral_bonus_cents}/></Field><Field label="Versão da regra"><input name="reward_terms_version" defaultValue={product.reward_terms_version || "2026-07-27"}/></Field><Field label="Janela de atribuição"><input name="attribution_window_days" type="number" defaultValue={product.attribution_window_days || 180}/></Field><Field label="Metragem/destaque"><input name="area_from" defaultValue={product.metadata?.area_from}/></Field><Field label="Condição"><input name="payment" defaultValue={product.metadata?.payment}/></Field><Field label="Imagem pública"><input name="image" defaultValue={product.metadata?.image}/></Field></div><UploadButton bucket="catalog-media" folder="produtos" onUploaded={result => { const input = document.querySelector('input[name="image"]'); if (input) input.value = result.publicUrl; }}/><Field label="Descrição do produto"><textarea name="description" rows="3" defaultValue={product.description}/></Field><Field label="Resumo da campanha"><textarea name="summary" rows="3" defaultValue={product.summary}/></Field><Field label="Diferenciais (um por linha)"><textarea name="features" rows="4" defaultValue={(product.metadata?.features || []).join("\n")}/></Field><Field label="Opções de interesse (uma por linha)"><textarea name="interest_options" rows="4" defaultValue={(product.interest_options || ["Quero conhecer o produto"]).join("\n")}/></Field><div className={styles.checkGrid}><label className={styles.check}><input name="public_visibility" type="checkbox" defaultChecked={product.public_visibility}/>Produto público</label><label className={styles.check}><input name="training_required" type="checkbox" defaultChecked={product.training_required ?? true}/>Treinamento obrigatório</label><label className={styles.check}><input name="alternative_discovery_enabled" type="checkbox" defaultChecked={product.alternative_discovery_enabled ?? true}/>Permitir alternativas com autorização</label></div><input type="hidden" name="alternative_discovery_scope" value="same_organization"/><button className="button button--orange">Salvar produto e campanha</button></form></Modal>}
  </>;
}

function BrokersSection({ data, onAction }) {
  const brokers = data?.brokers || []; const partners = data?.partners || []; const products = data?.catalog?.products || [];
  const [inviteResult, setInviteResult] = useState(null); const [assigning, setAssigning] = useState(null);
  async function invite(event) {
    event.preventDefault(); const form = new FormData(event.currentTarget);
    const metadata = { creci_number: form.get("creciNumber"), creci_state: form.get("creciState"), service_regions: String(form.get("regions") || "").split(",").map(v => v.trim()).filter(Boolean), capacity_per_day: form.get("capacity") || null };
    const created = await onAction("create_account_invite", { p_target_kind: "broker", p_email: form.get("email"), p_phone: form.get("phone"), p_display_name: form.get("displayName"), p_partner_id: form.get("partnerId"), p_access_role_code: null, p_membership_role: "read_only", p_metadata: metadata, p_expires_in_days: 7 }, false);
    setInviteResult(created); event.currentTarget.reset();
  }
  async function assign(event) { event.preventDefault(); const selected = Array.from(new FormData(event.currentTarget).getAll("products")); await onAction("set_broker_products", { p_broker_profile_id: assigning.profile_id, p_product_ids: selected }, true); setAssigning(null); }
  return <><div className={styles.twoColumn}><section className={styles.card}><span className="eyebrow">Corretores cadastrados pela gestão</span><h2>Controle, CRECI e escopo</h2>{brokers.map(b => <div className={styles.personRow} key={b.profile_id}><span className={styles.avatar}>{b.display_name?.split(" ").map(v => v[0]).slice(0,2).join("")}</span><span><b>{b.display_name}</b><small>CRECI {b.creci_state} {b.creci_number} · {b.partner_name || "Rede Conecta"}</small></span><Status value={b.status}/><button onClick={() => setAssigning(b)}>Produtos ({b.product_count})</button></div>)}{!brokers.length && <Empty/>}</section><section className={styles.card}><span className="eyebrow">Novo corretor</span><h2>Criar convite de acesso</h2><form className={styles.form} onSubmit={invite}><Field label="Nome"><input name="displayName" required/></Field><Field label="E-mail"><input name="email" type="email" required/></Field><Field label="WhatsApp"><input name="phone" required/></Field><Field label="Parceiro"><select name="partnerId" required><option value="">Selecione</option>{partners.map(p => <option value={p.id} key={p.id}>{p.name}</option>)}</select></Field><div className={styles.formGrid}><Field label="CRECI"><input name="creciNumber" required/></Field><Field label="UF"><input name="creciState" maxLength="2" required/></Field><Field label="Regiões"><input name="regions" placeholder="Monte Carmelo, Uberlândia"/></Field><Field label="Capacidade/dia"><input name="capacity" type="number" min="1"/></Field></div><button className="button button--orange">Criar convite</button></form>{inviteResult && <div className={styles.resultBox}><b>Link de ativação</b><code>{inviteResult.activation_url}</code><button onClick={() => navigator.clipboard.writeText(inviteResult.activation_url)}>Copiar</button></div>}</section></div>{assigning && <Modal title={`Produtos de ${assigning.display_name}`} onClose={() => setAssigning(null)}><form className={styles.form} onSubmit={assign}><div className={styles.checkList}>{products.map(product => <label key={product.id}><input type="checkbox" name="products" value={product.id}/><span><b>{product.name}</b><small>{product.category}</small></span></label>)}</div><button className="button button--orange">Salvar produtos</button></form></Modal>}</>;
}

function LeadDetail({ detail, onAction, onClose }) {
  const c = detail.connection; const [tab, setTab] = useState("overview");
  async function status(to) { const note = prompt("Observação da mudança de etapa:", ""); if (note === null) return; await onAction("transition_connection", { p_connection_id: c.id, p_to_status: to, p_note: note, p_loss_reason: to === "lost" ? note : "" }, true); onClose(); }
  async function activity(event) { event.preventDefault(); const form = new FormData(event.currentTarget); await onAction("add_activity", { p_connection_id: c.id, p_activity_type: form.get("type"), p_title: form.get("title"), p_notes: form.get("notes"), p_next_action_at: form.get("nextAction") || null }, false); location.reload(); }
  async function task(event) { event.preventDefault(); const form = new FormData(event.currentTarget); await onAction("upsert_task", { p_task_id: null, p_connection_id: c.id, p_payload: { title: form.get("title"), description: form.get("description"), priority: form.get("priority"), due_at: form.get("dueAt") || null, status: "pending" } }, false); location.reload(); }
  async function appointment(event) { event.preventDefault(); const form = new FormData(event.currentTarget); await onAction("upsert_appointment", { p_appointment_id: null, p_connection_id: c.id, p_payload: { appointment_type: form.get("type"), title: form.get("title"), starts_at: form.get("startsAt"), ends_at: form.get("endsAt") || null, location: form.get("location"), notes: form.get("notes"), status: "scheduled" } }, false); location.reload(); }
  async function deal(event) { event.preventDefault(); const form = new FormData(event.currentTarget); await onAction("upsert_deal", { p_deal_id: detail.deal?.id || null, p_connection_id: c.id, p_payload: { deal_number: form.get("dealNumber"), unit_reference: form.get("unit"), gross_value_cents: Math.round(Number(form.get("value") || 0) * 100), status: form.get("status"), notes: form.get("notes"), partner_id: c.partner_id, product_id: c.destination_product_id || c.source_product_id } }, true); onClose(); }
  const next = { new: "assigned", assigned: "accepted", accepted: "contacted", contacted: "qualified", qualified: "visit_scheduled", visit_scheduled: "proposal", proposal: "won" }[c.status];
  return <Modal title={`Lead ${c.protocol}`} onClose={onClose} wide><div className={styles.detailHeader}><div><Status value={c.status}/><h2>{detail.contact?.first_name || "Contato protegido"}</h2><p>{c.source_product_name_snapshot}</p></div><div className={styles.rowActions}>{next && <button className={styles.goodButton} onClick={() => status(next)}>Avançar para {connectionStatus[next]}</button>}{!['won','lost','cancelled'].includes(c.status) && <button className={styles.dangerButton} onClick={() => status("lost")}>Marcar perdido</button>}</div></div><div className={styles.detailTabs}>{["overview","activities","tasks","appointments","deal"].map(v => <button className={tab === v ? styles.activeFilter : ""} key={v} onClick={() => setTab(v)}>{({ overview: "Resumo", activities: "Atividades", tasks: "Tarefas", appointments: "Agenda", deal: "Negócio" })[v]}</button>)}</div>
    {tab === "overview" && <div className={styles.detailGrid}><section><h3>Contato</h3><dl className={styles.definition}><dt>Nome</dt><dd>{detail.contact?.first_name}</dd><dt>WhatsApp</dt><dd>{detail.contact?.phone || "Protegido"}</dd><dt>E-mail</dt><dd>{detail.contact?.email || "Protegido"}</dd><dt>Interesse</dt><dd>{c.interest_topic}</dd><dt>Melhor horário</dt><dd>{c.preferred_time}</dd></dl></section><section><h3>Proteção da origem</h3><dl className={styles.definition}><dt>Produto</dt><dd>{c.source_product_name_snapshot}</dd><dt>Protegido até</dt><dd>{dateOnly(c.protected_until)}</dd><dt>Conector</dt><dd>{c.connector_profile_id ? "Identificado no registro" : "Origem institucional"}</dd><dt>Alternativas</dt><dd>{c.alternative_discovery_authorized ? "Autorizadas" : "Não autorizadas"}</dd></dl></section></div>}
    {tab === "activities" && <div className={styles.detailGrid}><section><h3>Histórico</h3>{detail.activities?.map(a => <div className={styles.timeline} key={a.id}><i/><span><b>{a.title}</b><small>{when(a.occurred_at)} · {a.activity_type}</small><p>{a.notes}</p></span></div>)}{!detail.activities?.length && <Empty/>}</section><form className={styles.form} onSubmit={activity}><h3>Registrar atividade</h3><Field label="Tipo"><select name="type"><option value="call">Ligação</option><option value="whatsapp">WhatsApp</option><option value="email">E-mail</option><option value="note">Nota</option><option value="meeting">Reunião</option></select></Field><Field label="Título"><input name="title" required/></Field><Field label="Notas"><textarea name="notes" rows="4"/></Field><Field label="Próxima ação"><input name="nextAction" type="datetime-local"/></Field><button className="button button--orange">Registrar</button></form></div>}
    {tab === "tasks" && <div className={styles.detailGrid}><section><h3>Tarefas</h3>{detail.tasks?.map(t => <div className={styles.task} key={t.id}><Status value={t.status}/><span><b>{t.title}</b><small>{when(t.due_at)} · {t.priority}</small></span></div>)}{!detail.tasks?.length && <Empty/>}</section><form className={styles.form} onSubmit={task}><h3>Nova tarefa</h3><Field label="Título"><input name="title" required/></Field><Field label="Descrição"><textarea name="description"/></Field><Field label="Prioridade"><select name="priority"><option value="normal">Normal</option><option value="high">Alta</option><option value="urgent">Urgente</option></select></Field><Field label="Vencimento"><input name="dueAt" type="datetime-local"/></Field><button className="button button--orange">Criar tarefa</button></form></div>}
    {tab === "appointments" && <div className={styles.detailGrid}><section><h3>Agenda</h3>{detail.appointments?.map(a => <div className={styles.task} key={a.id}><Status value={a.status}/><span><b>{a.title}</b><small>{when(a.starts_at)} · {a.location}</small></span></div>)}{!detail.appointments?.length && <Empty/>}</section><form className={styles.form} onSubmit={appointment}><h3>Novo compromisso</h3><Field label="Tipo"><select name="type"><option value="call">Ligação</option><option value="video">Vídeo</option><option value="visit">Visita</option><option value="meeting">Reunião</option></select></Field><Field label="Título"><input name="title" required/></Field><Field label="Início"><input name="startsAt" type="datetime-local" required/></Field><Field label="Fim"><input name="endsAt" type="datetime-local"/></Field><Field label="Local"><input name="location"/></Field><Field label="Notas"><textarea name="notes"/></Field><button className="button button--orange">Agendar</button></form></div>}
    {tab === "deal" && <form className={styles.form} onSubmit={deal}><div className={styles.formGrid}><Field label="Número do negócio"><input name="dealNumber" defaultValue={detail.deal?.deal_number}/></Field><Field label="Unidade/lote"><input name="unit" defaultValue={detail.deal?.unit_reference}/></Field><Field label="Valor (R$)"><input name="value" type="number" step="0.01" defaultValue={Number(detail.deal?.gross_value_cents || 0) / 100}/></Field><Field label="Status"><select name="status" defaultValue={detail.deal?.status || "draft"}>{Object.entries(dealStatus).map(([v,l]) => <option value={v} key={v}>{l}</option>)}</select></Field></div><Field label="Notas"><textarea name="notes" rows="4" defaultValue={detail.deal?.notes}/></Field><button className="button button--orange">Salvar negócio</button></form>}
  </Modal>;
}

function LeadsSection({ data, onAction }) {
  const [detail, setDetail] = useState(null); const [search, setSearch] = useState("");
  const list = (data || []).filter(item => `${item.protocol} ${item.source_product_name_snapshot} ${item.partner_name}`.toLowerCase().includes(search.toLowerCase()));
  async function open(item) { setDetail(await request("connection_detail", { p_connection_id: item.id })); }
  return <><div className={styles.sectionHead}><div><span className="eyebrow">CRM operacional</span><h2>Leads conduzidos pela Rede Conecta</h2></div><input className={styles.search} value={search} onChange={e => setSearch(e.target.value)} placeholder="Buscar protocolo, produto ou parceiro"/></div><section className={styles.card}><div className={styles.tableWrap}><table><thead><tr><th>Protocolo</th><th>Produto</th><th>Parceiro</th><th>Etapa</th><th>Proteção</th><th>Próxima ação</th><th></th></tr></thead><tbody>{list.map(item => <tr key={item.id}><td><b>{item.protocol}</b><small>{dateOnly(item.submitted_at)}</small></td><td>{item.source_product_name_snapshot}</td><td>{item.partner_name || "—"}</td><td><Status value={item.status}/></td><td>{dateOnly(item.protected_until)}</td><td>{when(item.next_action_at)}</td><td><button onClick={() => open(item)}>Abrir</button></td></tr>)}</tbody></table></div>{!list.length && <Empty/>}</section>{detail && <LeadDetail detail={detail} onAction={onAction} onClose={() => setDetail(null)}/>}</>;
}

function DealsSection({ data, onAction }) {
  async function transition(item, status) { const reason = prompt("Observação:", "") ?? ""; await onAction("transition_deal", { p_deal_id: item.id, p_to_status: status, p_reason: reason }, true); }
  return <section className={styles.card}><div className={styles.sectionHead}><div><span className="eyebrow">Negócios</span><h2>Validação comercial e documental</h2></div></div><div className={styles.tableWrap}><table><thead><tr><th>Negócio</th><th>Origem</th><th>Produto</th><th>Parceiro</th><th>Valor</th><th>Status</th><th>Ações</th></tr></thead><tbody>{(data || []).map(item => <tr key={item.id}><td><b>{item.deal_number || item.protocol}</b><small>{item.unit_reference || "Unidade não definida"}</small></td><td>{item.protocol}</td><td>{item.product_name || item.source_product_name_snapshot}</td><td>{item.partner_name}</td><td>{money(item.gross_value_cents)}</td><td><Status value={item.status}/></td><td><div className={styles.rowActions}>{item.status === "draft" && <button onClick={() => transition(item, "reservation")}>Reserva</button>}{["reservation","contract_pending"].includes(item.status) && <button onClick={() => transition(item, "contracted")}>Contratado</button>}{item.status === "contracted" && <button className={styles.goodButton} onClick={() => transition(item, "validated")}>Validar</button>}{!['validated','cancelled','lost'].includes(item.status) && <button className={styles.dangerButton} onClick={() => transition(item, "cancelled")}>Cancelar</button>}</div></td></tr>)}</tbody></table></div>{!data?.length && <Empty/>}</section>;
}

function FinanceSection({ data, onAction, context }) {
  const rewards = data?.rewards || []; const payouts = data?.payouts || [];
  async function reward(item, to) { await onAction("transition_reward", { p_reward_id: item.id, p_to_status: to, p_reason: "Atualização pela gestão financeira", p_expected_payment_at: to === "scheduled" ? new Date(Date.now() + 7 * 86400000).toISOString() : null }, true); }
  return <><div className={styles.metrics}><Metric label="Pendente" value={money(data?.summary?.pending_cents)} icon="clock"/><Metric label="Aprovado/programado" value={money(data?.summary?.approved_cents)} icon="check"/><Metric label="Pago" value={money(data?.summary?.paid_cents)} icon="money"/></div><div className={styles.twoColumn}><section className={styles.card}><h2>Recompensas</h2>{rewards.map(r => <div className={styles.financeRow} key={r.id}><span><b>{r.connector_name}</b><small>{r.protocol} · {r.source_product_name_snapshot}</small></span><strong>{money(r.amount_cents)}</strong><Status value={r.status}/><div className={styles.rowActions}>{r.status === "pending" && <button onClick={() => reward(r, "approved")}>Aprovar</button>}{r.status === "approved" && <button onClick={() => reward(r, "scheduled")}>Programar</button>}</div></div>)}{!rewards.length && <Empty/>}</section><section className={styles.card}><h2>Lotes de pagamento</h2>{payouts.map(p => <div className={styles.financeRow} key={p.id}><span><b>{p.connector_name}</b><small>{dateOnly(p.scheduled_for)}</small></span><strong>{money(p.total_cents)}</strong><Status value={p.status}/></div>)}{!payouts.length && <Empty/>}</section></div></>;
}

function ReconciliationSection({ data, onAction }) {
  const [batch, setBatch] = useState(null); const partners = data?.partners || []; const reconciliation = data?.reconciliation || { batches: [], alerts: [] };
  async function createBatch(event) { event.preventDefault(); const f = new FormData(event.currentTarget); const result = await onAction("create_sales_batch", { p_partner_id: f.get("partnerId"), p_period_start: f.get("periodStart") || null, p_period_end: f.get("periodEnd") || null, p_file_name: f.get("fileName") || null }, false); setBatch(result.batch_id); }
  async function addRow(event) { event.preventDefault(); const f = new FormData(event.currentTarget); const result = await onAction("add_sales_row", { p_batch_id: batch, p_payload: { phone: f.get("phone"), email: f.get("email"), customer_reference: f.get("customer"), contract_reference: f.get("contract"), unit_reference: f.get("unit"), product_reference: f.get("product"), sale_date: f.get("saleDate"), gross_value_cents: Math.round(Number(f.get("value") || 0) * 100) } }, false); alert(`Linha processada: ${result.match_status}`); event.currentTarget.reset(); }
  async function finish() { await onAction("finish_sales_batch", { p_batch_id: batch }, true); setBatch(null); }
  async function resolve(alert, status) { const note = prompt("Resolução:", "") ?? ""; await onAction("resolve_alert", { p_alert_id: alert.id, p_status: status, p_resolution: note }, true); }
  return <><div className={styles.twoColumn}><section className={styles.card}><span className="eyebrow">Conciliação obrigatória</span><h2>Importar vendas do parceiro</h2>{!batch ? <form className={styles.form} onSubmit={createBatch}><Field label="Parceiro"><select name="partnerId" required><option value="">Selecione</option>{partners.map(p => <option value={p.id} key={p.id}>{p.name}</option>)}</select></Field><div className={styles.formGrid}><Field label="Período inicial"><input name="periodStart" type="date"/></Field><Field label="Período final"><input name="periodEnd" type="date"/></Field></div><Field label="Arquivo de origem"><input name="fileName" placeholder="relatorio-julho.csv"/></Field><button className="button button--orange">Abrir lote</button></form> : <><div className={styles.resultBox}><b>Lote em processamento</b><code>{batch}</code></div><form className={styles.form} onSubmit={addRow}><div className={styles.formGrid}><Field label="Telefone"><input name="phone"/></Field><Field label="E-mail"><input name="email" type="email"/></Field><Field label="Cliente/referência"><input name="customer"/></Field><Field label="Contrato"><input name="contract"/></Field><Field label="Unidade"><input name="unit"/></Field><Field label="Produto"><input name="product"/></Field><Field label="Data da venda"><input name="saleDate" type="date" required/></Field><Field label="Valor (R$)"><input name="value" type="number" step="0.01"/></Field></div><button className="button button--navy">Processar linha</button><button type="button" className="button button--light" onClick={finish}>Finalizar lote</button></form></>}</section><section className={styles.card}><span className="eyebrow">Histórico</span><h2>Lotes processados</h2>{reconciliation.batches?.map(b => <div className={styles.financeRow} key={b.id}><span><b>{b.partner_name}</b><small>{dateOnly(b.period_start)} a {dateOnly(b.period_end)}</small></span><span>{b.total_rows} linhas</span><Status value={b.status}/></div>)}{!reconciliation.batches?.length && <Empty/>}</section></div><section className={styles.card} style={{ marginTop: 18 }}><div className={styles.cardHead}><h2>Alertas de possível circunvenção</h2><b>{reconciliation.open_count || 0} abertos</b></div>{reconciliation.alerts?.map(a => <div className={styles.alertRow} key={a.id}><Status value={a.severity}/><span><b>{a.summary}</b><small>{a.partner_name} · {a.protocol || "Sem protocolo"} · {when(a.created_at)}</small></span><Status value={a.status}/><div className={styles.rowActions}>{a.status === "open" && <button onClick={() => resolve(a, "under_review")}>Analisar</button>}{!['resolved','dismissed'].includes(a.status) && <><button className={styles.goodButton} onClick={() => resolve(a, "resolved")}>Resolver</button><button onClick={() => resolve(a, "dismissed")}>Descartar</button></>}</div></div>)}{!reconciliation.alerts?.length && <Empty>Nenhuma divergência encontrada.</Empty>}</section></>;
}

function NotificationsSection({ data, process, onReload, manualResults }) {
  return <section className={styles.card}><div className={styles.sectionHead}><div><span className="eyebrow">E-mail e WhatsApp</span><h2>Fila de comunicações</h2></div><button className="button button--orange" onClick={process}>Processar fila</button></div>{manualResults?.length > 0 && <div className={styles.manualPanel}><b>Envios manuais necessários</b>{manualResults.filter(r => r.manualUrl).map(r => <a key={r.id} href={r.manualUrl} target="_blank">Abrir {r.channel} para {r.recipient}</a>)}</div>}<div className={styles.tableWrap}><table><thead><tr><th>Canal</th><th>Destinatário</th><th>Modelo</th><th>Status</th><th>Tentativas</th><th>Data</th></tr></thead><tbody>{(data || []).map(n => <tr key={n.id}><td>{n.channel}</td><td>{n.recipient}</td><td>{n.template_code}</td><td><Status value={n.status}/></td><td>{n.attempts}</td><td>{when(n.created_at)}</td></tr>)}</tbody></table></div>{!data?.length && <Empty/>}</section>;
}

function AuditSection({ data }) { return <section className={styles.card}><span className="eyebrow">Governança</span><h2>Trilha de auditoria</h2>{(data || []).map(a => <div className={styles.auditRow} key={a.id}><span className={styles.auditIcon}><Icon name="shield" size={17}/></span><span><b>{a.action}</b><small>{a.actor_name || "Sistema"} · {a.entity_type} · {when(a.created_at)}</small></span><code>{a.entity_id?.slice(0,8)}</code></div>)}{!data?.length && <Empty/>}</section>; }

function SettingsSection({ data, onAction }) {
  async function save(event) { event.preventDefault(); const f = new FormData(event.currentTarget); let value; try { value = JSON.parse(f.get("value")); } catch { value = f.get("value"); } await onAction("set_setting", { p_key: f.get("key"), p_value: value }, true); }
  return <div className={styles.twoColumn}><section className={styles.card}><span className="eyebrow">Parâmetros operacionais</span><h2>Configurações</h2>{Object.entries(data?.settings || {}).map(([key,value]) => <div className={styles.settingRow} key={key}><b>{key}</b><code>{JSON.stringify(value)}</code></div>)}{!Object.keys(data?.settings || {}).length && <Empty/>}</section><section className={styles.card}><h2>Definir parâmetro</h2><form className={styles.form} onSubmit={save}><Field label="Chave"><input name="key" required placeholder="operations.default_sla_minutes"/></Field><Field label="Valor JSON"><textarea name="value" rows="5" required placeholder="30 ou {&quot;enabled&quot;:true}"/></Field><button className="button button--orange">Salvar</button></form></section></div>;
}

function ConnectorPortal({ snapshot, reload, onAction }) {
  const data = snapshot || { summary: {}, campaigns: [], links: [], connections: [], rewards: [] };
  async function createLink(campaign) {
    const result = await onAction("create_invitation", { p_campaign_id: campaign.campaign_id, p_label: `${campaign.product_name} · compartilhamento`, p_expires_in_days: 90 }, false);
    const row = Array.isArray(result) ? result[0] : result;
    if (row?.invitation_code) location.href = `/compartilhar/${row.invitation_code}`;
  }
  return <><div className={styles.metrics}><Metric label="Links ativos" value={data.summary?.links || 0} icon="link"/><Metric label="Indicações" value={data.summary?.connections || 0} icon="user"/><Metric label="Negócios concluídos" value={data.summary?.won_connections || 0} icon="check"/><Metric label="Recompensas pagas" value={money(data.summary?.paid_rewards_cents)} icon="money"/></div><section className={styles.card}><span className="eyebrow">Produtos disponíveis</span><h2>Escolha, personalize e compartilhe</h2><div className={styles.gridCards}>{data.campaigns?.map(c => <article className={styles.connectorProduct} key={c.campaign_id}><span>{c.category}</span><h3>{c.product_name}</h3><p>{c.description}</p><dl className={styles.definition}><dt>Localização</dt><dd>{c.location}</dd><dt>Recompensa</dt><dd>{money(c.reward_amount_cents)}</dd></dl><button className="button button--orange" onClick={() => createLink(c)}>Gerar link oficial</button></article>)}</div></section><div className={styles.twoColumn} style={{ marginTop: 18 }}><section className={styles.card}><h2>Meus links</h2>{data.links?.map(l => <div className={styles.linkPortalRow} key={l.id}><span><b>{l.product_name_snapshot}</b><small>{l.views} visualizações · {l.shares} compartilhamentos</small></span><div className={styles.rowActions}><Link href={`/compartilhar/${l.public_code}`}>Personalizar</Link><button onClick={() => navigator.clipboard.writeText(`${location.origin}/convite/${l.public_code}`)}>Copiar</button></div></div>)}{!data.links?.length && <Empty/>}</section><section className={styles.card}><h2>Extrato de recompensas</h2>{data.rewards?.map(r => <div className={styles.financeRow} key={r.id}><span><b>{r.source_product_name_snapshot}</b><small>{r.protocol}</small></span><strong>{money(r.amount_cents)}</strong><Status value={r.status}/></div>)}{!data.rewards?.length && <Empty/>}</section></div><section className={styles.card} style={{ marginTop: 18 }}><h2>Acompanhamento das indicações</h2><div className={styles.tableWrap}><table><thead><tr><th>Protocolo</th><th>Produto</th><th>Status</th><th>Interesse</th><th>Início</th><th>Proteção</th></tr></thead><tbody>{data.connections?.map(c => <tr key={c.protocol}><td>{c.protocol}</td><td>{c.source_product_name_snapshot}</td><td><Status value={c.status}/></td><td>{c.interest_topic}</td><td>{dateOnly(c.submitted_at)}</td><td>{dateOnly(c.protected_until)}</td></tr>)}</tbody></table></div></section></>;
}

function PartnerPortal({ snapshot, onAction }) {
  const data = snapshot || { summary: {}, developments: [], pipeline: [] }; const partner = data.partner || {};
  async function accept() { await onAction("accept_partner_terms", { p_terms_version: PARTNER_TERMS_VERSION, p_ip_hmac: null, p_user_agent_hash: null }, true); }
  return <><div className={styles.partnerNotice}><Icon name="shield"/><span><b>Operação centralizada e origem protegida</b>{data.notice}</span></div>{!partner.terms_accepted_at && <div className={styles.termsBanner}><span><b>Termo de não circunvenção pendente</b>O painel não disponibiliza dados pessoais. O aceite formaliza a preservação dos leads e negócios originados pela Rede Conecta.</span><button className="button button--orange" onClick={accept}>Aceitar versão {PARTNER_TERMS_VERSION}</button></div>}<div className={styles.metrics}><Metric label="Conexões protegidas" value={data.summary?.protected_connections || 0} icon="shield"/><Metric label="Em andamento" value={data.summary?.open_connections || 0} icon="target"/><Metric label="Negócios validados" value={data.summary?.validated_deals || 0} icon="check"/><Metric label="VGV validado" value={money(data.summary?.validated_vgv_cents)} icon="money"/></div><div className={styles.twoColumn}><section className={styles.card}><span className="eyebrow">Empreendimentos vinculados</span><h2>{partner.name}</h2>{data.developments?.map(d => <div className={styles.developmentRow} key={d.id}><span><b>{d.name}</b><small>{d.city} · {d.state}</small></span><Status value={d.status}/><strong>{d.product_count} produtos</strong></div>)}</section><section className={styles.card}><span className="eyebrow">Governança</span><h2>Situação contratual</h2><dl className={styles.definition}><dt>Status</dt><dd><Status value={partner.status}/></dd><dt>Contrato</dt><dd><Status value={partner.contract_status}/></dd><dt>Janela de proteção</dt><dd>{partner.attribution_window_days} dias</dd><dt>Reconciliação</dt><dd>{partner.reconciliation_required ? "Obrigatória" : "Não obrigatória"}</dd><dt>Alertas abertos</dt><dd>{data.summary?.open_reconciliation_alerts || 0}</dd></dl></section></div><section className={styles.card} style={{ marginTop: 18 }}><h2>Pipeline de leitura</h2><p className={styles.muted}>Nenhum nome, telefone, e-mail, documento ou anotação interna é exibido neste painel.</p><div className={styles.tableWrap}><table><thead><tr><th>Protocolo</th><th>Produto</th><th>Etapa</th><th>Início</th><th>Proteção</th><th>Negócio</th><th>Valor</th></tr></thead><tbody>{data.pipeline?.map(c => <tr key={c.protocol}><td>{c.protocol}</td><td>{c.source_product_name_snapshot}</td><td><Status value={c.status}/></td><td>{dateOnly(c.submitted_at)}</td><td>{dateOnly(c.protected_until)}</td><td><Status value={c.deal_status || "—"}/></td><td>{c.gross_value_cents ? money(c.gross_value_cents) : "—"}</td></tr>)}</tbody></table></div></section></>;
}

function BrokerPortal({ snapshot }) {
  const data = snapshot || { products: [], stage_totals: {} }; const broker = data.broker || {};
  return <><div className={styles.partnerNotice}><Icon name="shield"/><span><b>Painel exclusivamente de leitura</b>{data.notice}</span></div><div className={styles.metrics}><Metric label="Produtos vinculados" value={data.products?.length || 0} icon="building"/><Metric label="Leads novos" value={data.stage_totals?.new || 0} icon="user"/><Metric label="Em proposta" value={data.stage_totals?.proposal || 0} icon="target"/><Metric label="Concluídos" value={data.stage_totals?.won || 0} icon="check"/></div><section className={styles.card}><div className={styles.sectionHead}><div><span className="eyebrow">Corretor credenciado</span><h2>{broker.display_name}</h2><p>CRECI {broker.creci_state} {broker.creci_number}</p></div><Status value={broker.status}/></div><div className={styles.gridCards}>{data.products?.map(p => <article className={styles.productAdmin} key={p.product_id}><Status value={p.status}/><h3>{p.product_name}</h3><p>{p.category} · {p.service_region}</p><dl className={styles.definition}><dt>Campanhas ativas</dt><dd>{p.campaign_count}</dd><dt>Leads em andamento</dt><dd>{p.open_connections}</dd><dt>Negócios concluídos</dt><dd>{p.won_connections}</dd><dt>Treinamento</dt><dd>{p.training_compliant ? "Regular" : "Pendente"}</dd></dl></article>)}</div>{!data.products?.length && <Empty>Nenhum produto foi vinculado ao seu perfil.</Empty>}</section></>;
}

export default function Portal({ initialContext, initialSnapshot }) {
  const context = initialContext; const [active, setActive] = useState("dashboard"); const [data, setData] = useState(initialSnapshot); const [loading, setLoading] = useState(false); const [toast, setToast] = useState(null); const [manualResults, setManualResults] = useState([]);
  const permissions = context.permissions || []; const has = permission => permissions.includes("platform.all") || permissions.includes(permission);
  const menu = useMemo(() => context.portal_kind !== "staff" ? [] : [
    ["dashboard","Visão geral","chart",true],["connectors","Conectores","user",has("connectors.read")],["staff","Equipe e acessos","shield",has("staff.manage")],["partners","Parceiros","handshake",has("partners.manage")],["catalog","Empreendimentos","building",has("catalog.manage")],["brokers","Corretores","user",has("brokers.manage")],["leads","Leads e CRM","target",has("leads.read")],["deals","Negócios","check",has("deals.manage")],["finance","Financeiro","money",has("rewards.manage") || has("payouts.manage")],["reconciliation","Conciliação","shield",has("sales.reconcile")],["notifications","Comunicações","link",has("notifications.manage")],["audit","Auditoria","shield",has("audit.read")],["settings","Configurações","menu",has("settings.manage")]
  ].filter(item => item[3]), [context.portal_kind, permissions.join("|")]);

  async function load(section = active) {
    setLoading(true);
    try {
      let result;
      if (section === "dashboard") result = await request("dashboard");
      if (section === "connectors") result = await request("connector_applications", { p_status: null, p_limit: 500 });
      if (section === "staff") { const [staff, roles] = await Promise.all([request("staff"), request("access_roles")]); result = { staff, roles }; }
      if (section === "partners") result = await request("partners");
      if (section === "catalog") { const [catalog, partners] = await Promise.all([request("catalog"), request("partners")]); result = { catalog, partners }; }
      if (section === "brokers") { const [brokers, partners, catalog] = await Promise.all([request("brokers"), request("partners"), request("catalog")]); result = { brokers, partners, catalog }; }
      if (section === "leads") result = await request("connections", { p_status: null, p_partner_id: null, p_limit: 1000 });
      if (section === "deals") result = await request("deals", { p_status: null });
      if (section === "finance") result = await request("finance");
      if (section === "reconciliation") { const [reconciliation, partners] = await Promise.all([request("reconciliation"), request("partners")]); result = { reconciliation, partners }; }
      if (section === "notifications") result = await request("notifications", { p_status: null, p_limit: 500 });
      if (section === "audit") result = await request("audit", { p_limit: 500 });
      if (section === "settings") result = await request("settings");
      if (context.portal_kind === "connector") result = await request("connector_snapshot");
      if (context.portal_kind === "partner") result = await request("partner_snapshot");
      if (context.portal_kind === "broker") result = await request("broker_snapshot");
      setData(result);
    } catch (error) { setToast({ type: "error", message: error.message }); }
    finally { setLoading(false); }
  }

  async function action(operation, params, reload = false) {
    setLoading(true);
    try { const result = await request(operation, params); setToast({ type: "success", message: "Operação concluída e registrada na auditoria." }); if (reload) await load(active); return result; }
    catch (error) { setToast({ type: "error", message: error.message }); throw error; }
    finally { setLoading(false); }
  }

  async function processNotifications() {
    setLoading(true);
    try { const response = await fetch("/api/notifications/process", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ limit: 30 }) }); const result = await response.json(); if (!response.ok) throw new Error(result.error); setManualResults(result.results || []); setToast({ type: "success", message: `${result.processed || 0} comunicações processadas.` }); if (active === "notifications") await load("notifications"); }
    catch (error) { setToast({ type: "error", message: error.message }); }
    finally { setLoading(false); }
  }

  if (context.portal_kind === "pending" || context.profile_status !== "active") return <PendingPortal context={context}/>;
  if (context.portal_kind === "connector") return <div className={styles.externalShell}><header className={styles.externalHeader}><NetworkMark/><div><span>Conector</span><b>{context.display_name}</b><button onClick={() => fetch("/api/auth/logout", { method: "POST" }).then(() => location.href = "/")}>Sair</button></div></header><main className={styles.externalMain}>{loading && <div className={styles.loadingBar}/>}<ConnectorPortal snapshot={data} reload={load} onAction={action}/></main><Toast toast={toast} onClose={() => setToast(null)}/></div>;
  if (context.portal_kind === "partner") return <div className={styles.externalShell}><header className={styles.externalHeader}><NetworkMark/><div><span>Parceiro</span><b>{context.display_name}</b><button onClick={() => fetch("/api/auth/logout", { method: "POST" }).then(() => location.href = "/")}>Sair</button></div></header><main className={styles.externalMain}>{loading && <div className={styles.loadingBar}/>}<PartnerPortal snapshot={data} onAction={action}/></main><Toast toast={toast} onClose={() => setToast(null)}/></div>;
  if (context.portal_kind === "broker") return <div className={styles.externalShell}><header className={styles.externalHeader}><NetworkMark/><div><span>Corretor</span><b>{context.display_name}</b><button onClick={() => fetch("/api/auth/logout", { method: "POST" }).then(() => location.href = "/")}>Sair</button></div></header><main className={styles.externalMain}><BrokerPortal snapshot={data}/></main></div>;

  function choose(section) { setActive(section); setData(section === "dashboard" ? initialSnapshot : null); setTimeout(() => load(section), 0); }
  return <div className={styles.shell}><aside className={styles.sidebar}><NetworkMark inverse/><nav>{menu.map(([key,label,icon]) => <button key={key} className={active === key ? styles.navActive : ""} onClick={() => choose(key)}><Icon name={icon}/><span>{label}</span></button>)}</nav><div className={styles.sidebarSecurity}><Icon name="shield"/><span><b>Operação Rede Conecta</b>Parceiros e corretores permanecem em leitura.</span></div></aside><div className={styles.main}><header className={styles.topbar}><div><span className="eyebrow">Central de gestão</span><h1>{menu.find(item => item[0] === active)?.[1] || "Rede Conecta"}</h1></div><div className={styles.user}><span className={styles.avatar}>{context.display_name?.split(" ").map(v => v[0]).slice(0,2).join("")}</span><span><b>{context.display_name}</b><small>Equipe interna</small></span><button onClick={() => fetch("/api/auth/logout", { method: "POST" }).then(() => location.href = "/")}>Sair</button></div></header>{loading && <div className={styles.loadingBar}/>}<main className={styles.content}>{active === "dashboard" && <StaffDashboard data={data}/>} {active === "connectors" && <ConnectorsSection data={data} onAction={action} processing={processNotifications}/>} {active === "staff" && <StaffSection data={data} onAction={action}/>} {active === "partners" && <PartnersSection data={data} onAction={action}/>} {active === "catalog" && <CatalogSection data={data} onAction={action}/>} {active === "brokers" && <BrokersSection data={data} onAction={action}/>} {active === "leads" && <LeadsSection data={data} onAction={action}/>} {active === "deals" && <DealsSection data={data} onAction={action}/>} {active === "finance" && <FinanceSection data={data} onAction={action} context={context}/>} {active === "reconciliation" && <ReconciliationSection data={data} onAction={action}/>} {active === "notifications" && <NotificationsSection data={data} process={processNotifications} manualResults={manualResults}/>} {active === "audit" && <AuditSection data={data}/>} {active === "settings" && <SettingsSection data={data} onAction={action}/>}</main></div><Toast toast={toast} onClose={() => setToast(null)}/></div>;
}
